policies=Table("risk_policy_versions",metadata,Column("policy_version_id",Uuid,primary_key=True),Column("policy_id",Uuid,nullable=False),Column("name",String,nullable=False),Column("version",String,nullable=False),Column("account_id",Uuid,nullable=False),Column("market",String,nullable=False),Column("required_scopes",JSON,nullable=False),Column("effective_from",Date,nullable=False),Column("effective_to",Date),Column("owner",String,nullable=False),Column("max_input_age_seconds",Integer,nullable=False),UniqueConstraint("policy_id","version"))
