runs=Table("risk_check_runs",metadata,Column("run_id",Uuid,primary_key=True),Column("account_id",Uuid,nullable=False),Column("object_id",Uuid,nullable=False),Column("policy_version_id",Uuid,ForeignKey("risk_policy_versions.policy_version_id"),nullable=False),Column("stage",String,nullable=False),Column("decision_at",DateTime(timezone=True),nullable=False),Column("input_hash",String,unique=True,nullable=False),Column("status",String,nullable=False),Column("decision",String,nullable=False),Column("started_at",DateTime(timezone=True),nullable=False),Column("completed_at",DateTime(timezone=True)),Column("error",String))
results=Table("risk_check_results",metadata,Column("result_id",Uuid,primary_key=True),Column("run_id",Uuid,ForeignKey("risk_check_runs.run_id"),nullable=False),Column("rule_version_id",Uuid,ForeignKey("risk_rule_versions.version_id"),nullable=False),Column("object_id",Uuid,nullable=False),Column("scope",String,nullable=False),Column("metric",String,nullable=False),Column("observed",JSON,nullable=False),Column("threshold",JSON,nullable=False),Column("operator",String,nullable=False),Column("severity",String,nullable=False),Column("outcome",String,nullable=False),Column("explanation",String,nullable=False),Column("evaluated_at",DateTime(timezone=True),nullable=False))
exceptions=Table("risk_exceptions",metadata,Column("exception_id",Uuid,primary_key=True),Column("result_id",Uuid,ForeignKey("risk_check_results.result_id"),nullable=False),Column("rule_version_id",Uuid,ForeignKey("risk_rule_versions.version_id"),nullable=False),Column("scope",String,nullable=False),Column("requested_by",String,nullable=False),Column("approved_by",String,nullable=False),Column("reason",String,nullable=False),Column("approved_at",DateTime(timezone=True),nullable=False),Column("expires_at",DateTime(timezone=True),nullable=False),Column("status",String,nullable=False),Column("version",Integer,nullable=False))
alerts=Table("risk_alerts",metadata,Column("alert_id",Uuid,primary_key=True),Column("account_id",Uuid,nullable=False),Column("object_id",Uuid,nullable=False),Column("result_id",Uuid,ForeignKey("risk_check_results.result_id"),nullable=False),Column("rule_version_id",Uuid,ForeignKey("risk_rule_versions.version_id"),nullable=False),Column("scope",String,nullable=False),Column("observation_window",String,nullable=False),Column("dedupe_key",String,unique=True,nullable=False),Column("status",String,nullable=False),Column("opened_at",DateTime(timezone=True),nullable=False),Column("version",Integer,nullable=False),Column("acknowledged_by",String),Column("acknowledged_at",DateTime(timezone=True)),Column("escalated_to",String),Column("resolved_at",DateTime(timezone=True)),Column("resolution_evidence",String))
events=Table("risk_events",metadata,Column("event_id",Uuid,primary_key=True),Column("event_type",String,nullable=False),Column("account_id",Uuid,nullable=False),Column("object_id",Uuid,nullable=False),Column("occurred_at",DateTime(timezone=True),nullable=False),Column("payload",JSON,nullable=False))
